import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"Рабочая область","description":"","frontmatter":{},"headers":[],"relativePath":"ru/concepts/workspace.md","filePath":"ru/concepts/workspace.md","lastUpdated":1784904021000}'),n={name:"ru/concepts/workspace.md"};function p(l,a,h,d,o,c){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="рабочая-область" tabindex="-1">Рабочая область <a class="header-anchor" href="#рабочая-область" aria-label="Permalink to &quot;Рабочая область&quot;">​</a></h1><p>Рабочая область — это директория, в которой swag2mcp хранит все свои данные: конфиг, кэшированные спецификации, локальные файлы спецификаций, сохранённые ответы и скрипты аутентификации.</p><h2 id="структура" tabindex="-1">Структура <a class="header-anchor" href="#структура" aria-label="Permalink to &quot;Структура&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.swag2mcp/                          # Корень рабочей области (по умолчанию)</span></span>
<span class="line"><span>├── swag2mcp.yaml                     # Файл конфигурации</span></span>
<span class="line"><span>├── cache/                            # Кэшированные удалённые файлы спецификаций</span></span>
<span class="line"><span>│   ├── a1b2c3d4e5f6...spec          # Содержимое кэшированной спецификации</span></span>
<span class="line"><span>│   └── a1b2c3d4e5f6...meta          # Метаданные кэша (JSON)</span></span>
<span class="line"><span>├── specs/                            # Локальные файлы спецификаций</span></span>
<span class="line"><span>│   └── my-api.yaml</span></span>
<span class="line"><span>├── responses/                        # Сохранённые ответы API (большие ответы)</span></span>
<span class="line"><span>│   ├── meteo-get-forecast-abc123.json</span></span>
<span class="line"><span>│   └── response-fragment-def456.json</span></span>
<span class="line"><span>└── auth_scripts/                     # Скрипты аутентификации</span></span>
<span class="line"><span>    ├── meteo.sh                      # Unix shell-скрипт</span></span>
<span class="line"><span>    └── meteo.bat                     # Windows batch-скрипт</span></span></code></pre></div><h2 id="путь-по-умолчанию" tabindex="-1">Путь по умолчанию <a class="header-anchor" href="#путь-по-умолчанию" aria-label="Permalink to &quot;Путь по умолчанию&quot;">​</a></h2><ul><li><strong>Linux/macOS</strong>: <code>~/.swag2mcp/</code></li><li><strong>Windows</strong>: <code>%USERPROFILE%\\.swag2mcp\\</code></li></ul><h2 id="пользовательскии-путь" tabindex="-1">Пользовательский путь <a class="header-anchor" href="#пользовательскии-путь" aria-label="Permalink to &quot;Пользовательский путь&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /путь/до/workspace</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./my-workspace</span></span></code></pre></div><h2 id="директории" tabindex="-1">Директории <a class="header-anchor" href="#директории" aria-label="Permalink to &quot;Директории&quot;">​</a></h2><h3 id="cache" tabindex="-1">cache/ <a class="header-anchor" href="#cache" aria-label="Permalink to &quot;cache/&quot;">​</a></h3><p>Хранит скачанные удалённые файлы спецификаций. Каждый файл кэшируется с SHA-256 хешем его URL в качестве имени файла:</p><ul><li><code>{hash}.spec</code> — содержимое кэшированного файла спецификации</li><li><code>{hash}.meta</code> — JSON-метаданные (исходный URL, время кэширования, TTL)</li></ul><p>Каждый кэшированный файл имеет случайный TTL от 1 часа до 48 часов. Кэш автоматически проверяется при каждом запуске — если существует валидная (непросроченная) запись, она используется повторно без загрузки.</p><p><strong>Команды:</strong></p><ul><li><code>swag2mcp update</code> — очищает кэш и перезагружает все спецификации</li><li><code>swag2mcp clean</code> — очищает кэш и ответы</li></ul><h3 id="specs" tabindex="-1">specs/ <a class="header-anchor" href="#specs" aria-label="Permalink to &quot;specs/&quot;">​</a></h3><p>Хранит локальные файлы спецификаций, на которые коллекции ссылаются через <code>location: specs/{name}</code>. Файлы здесь используются напрямую без кэширования.</p><p>Эта директория заполняется:</p><ul><li><code>swag2mcp import &amp;lt;source&amp;gt; &amp;lt;name&amp;gt;</code> — скачивает удалённую спецификацию и сохраняет её сюда</li><li><code>swag2mcp export</code> — копирует спецификации сюда в экспортный ZIP</li><li>Вручную — вы можете скопировать файлы спецификаций сюда самостоятельно</li></ul><h3 id="responses" tabindex="-1">responses/ <a class="header-anchor" href="#responses" aria-label="Permalink to &quot;responses/&quot;">​</a></h3><p>Хранит ответы API, превышающие лимит <code>max_response_size</code> (по умолчанию 1 МБ). Когда LLM вызывает эндпоинт и ответ слишком велик, swag2mcp сохраняет его сюда и возвращает ссылку на файл.</p><p>Соглашение об именовании: <code>{domain}-{method}-{path_with_underscores}-{6симв_hex}.json</code></p><p>Старые ответы автоматически очищаются через 48 часов при запуске MCP-сервера.</p><h3 id="auth-scripts" tabindex="-1">auth_scripts/ <a class="header-anchor" href="#auth-scripts" aria-label="Permalink to &quot;auth_scripts/&quot;">​</a></h3><p>Хранит скрипты аутентификации для типа <code>script</code>. Каждый скрипт назван по домену спецификации.</p><h4 id="соглашение-об-именовании" tabindex="-1">Соглашение об именовании <a class="header-anchor" href="#соглашение-об-именовании" aria-label="Permalink to &quot;Соглашение об именовании&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Платформа</th><th>Имя файла</th><th>Пример</th></tr></thead><tbody><tr><td>Unix (Linux, macOS)</td><td><code>{domain}.sh</code></td><td><code>meteo.sh</code></td></tr><tr><td>Windows</td><td><code>{domain}.bat</code></td><td><code>meteo.bat</code></td></tr></tbody></table><p>Домен не должен содержать символы <code>/</code> или <code>\\</code>.</p><h4 id="как-работают-скрипты" tabindex="-1">Как работают скрипты <a class="header-anchor" href="#как-работают-скрипты" aria-label="Permalink to &quot;Как работают скрипты&quot;">​</a></h4><ol><li>swag2mcp запускает скрипт с таймаутом 30 секунд</li><li>Скрипт должен вывести валидный JSON в stdout</li><li>swag2mcp разбирает JSON и использует токен для API-запросов</li></ol><h4 id="ожидаемыи-формат-вывода" tabindex="-1">Ожидаемый формат вывода <a class="header-anchor" href="#ожидаемыи-формат-вывода" aria-label="Permalink to &quot;Ожидаемый формат вывода&quot;">​</a></h4><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ваш-токен-здесь&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3600</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Поле</th><th>Тип</th><th>Обязательно</th><th>Описание</th></tr></thead><tbody><tr><td><code>token</code></td><td>string</td><td>✅</td><td>Токен аутентификации</td></tr><tr><td><code>access_token</code></td><td>string</td><td>❌</td><td>Альтернатива <code>token</code> (проверяется в первую очередь)</td></tr><tr><td><code>token_type</code></td><td>string</td><td>❌</td><td>Тип токена (например, &quot;Bearer&quot;)</td></tr><tr><td><code>expires_in</code></td><td>number</td><td>❌</td><td>Время жизни токена в секундах (по умолчанию: 3600)</td></tr></tbody></table><h4 id="выполнение" tabindex="-1">Выполнение <a class="header-anchor" href="#выполнение" aria-label="Permalink to &quot;Выполнение&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Платформа</th><th>Команда</th></tr></thead><tbody><tr><td>Unix</td><td><code>sh {domain}.sh</code></td></tr><tr><td>Windows</td><td><code>cmd /c {domain}.bat</code></td></tr></tbody></table><h4 id="кэширование-токена" tabindex="-1">Кэширование токена <a class="header-anchor" href="#кэширование-токена" aria-label="Permalink to &quot;Кэширование токена&quot;">​</a></h4><p>Токен кэшируется в памяти до истечения срока действия. При каждом вызове API swag2mcp сначала проверяет кэш — скрипт выполняется только когда кэшированный токен истёк.</p><h4 id="создание-заглушки" tabindex="-1">Создание заглушки <a class="header-anchor" href="#создание-заглушки" aria-label="Permalink to &quot;Создание заглушки&quot;">​</a></h4><p>Когда вы настраиваете <code>auth: { type: script, config: { domain: &quot;myapi&quot; } }</code>, swag2mcp автоматически создаёт скрипт-заглушку:</p><p><strong>Unix (<code>auth_scripts/myapi.sh</code>):</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#!/bin/sh</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;token&quot;: &quot;ваш-токен-здесь&quot;, &quot;expires_in&quot;: 3600}&#39;</span></span></code></pre></div><p><strong>Windows (<code>auth_scripts/myapi.bat</code>):</strong></p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">@echo</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> off</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ваш-токен-здесь&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;expires_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 3600}</span></span></code></pre></div><p>Замените токен-заполнитель на вашу реальную логику аутентификации.</p><h4 id="очистка-осиротевших-скриптов" tabindex="-1">Очистка осиротевших скриптов <a class="header-anchor" href="#очистка-осиротевших-скриптов" aria-label="Permalink to &quot;Очистка осиротевших скриптов&quot;">​</a></h4><p>Когда вы удаляете спецификацию, её скрипт аутентификации становится осиротевшим. swag2mcp автоматически удаляет осиротевшие скрипты при:</p><ul><li><code>swag2mcp update</code></li><li><code>swag2mcp clean</code></li></ul><h2 id="команды" tabindex="-1">Команды <a class="header-anchor" href="#команды" aria-label="Permalink to &quot;Команды&quot;">​</a></h2><h3 id="update" tabindex="-1">update <a class="header-anchor" href="#update" aria-label="Permalink to &quot;update&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Проверяет конфиг, очищает кэш и ответы, затем перезагружает все файлы спецификаций. Также проверяет наличие скриптов аутентификации и удаляет осиротевшие скрипты.</p><p>Используйте эту команду после:</p><ul><li>Добавления или удаления коллекций</li><li>Изменения location коллекций</li><li>Редактирования файлов спецификаций, требующих перекэширования</li></ul><h3 id="clean" tabindex="-1">clean <a class="header-anchor" href="#clean" aria-label="Permalink to &quot;clean&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clean</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Удаляет всё содержимое <code>cache/</code> и <code>responses/</code>, а также осиротевшие скрипты аутентификации. НЕ перекэширует спецификации — для этого используйте <code>update</code>.</p><h3 id="validate" tabindex="-1">validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;validate&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> validate</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [path]</span></span></code></pre></div><p>Проверяет конфиг, включая все location коллекций. Подробнее: <a href="./../cli/validate">CLI: validate</a>.</p><h2 id="экспорт-и-импорт" tabindex="-1">Экспорт и импорт <a class="header-anchor" href="#экспорт-и-импорт" aria-label="Permalink to &quot;Экспорт и импорт&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Экспорт рабочей области в ZIP (имя по умолчанию: swag2mcp-backup-{date}.zip)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Экспорт по конкретному пути</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /путь/до/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /путь/до/backup.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Экспорт только определённых спецификаций</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Восстановление из резервной копии</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /путь/до/backup.zip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /путь/до/workspace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /путь/до/backup.zip</span></span></code></pre></div><p>Экспорт включает: <code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>. Кэш и ответы исключены (это локальные данные).</p><h2 id="gitignore" tabindex="-1">.gitignore <a class="header-anchor" href="#gitignore" aria-label="Permalink to &quot;.gitignore&quot;">​</a></h2><p>Если ваша рабочая область находится внутри Git-репозитория, добавьте эти записи в <code>.gitignore</code>:</p><div class="language-gitignore vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">gitignore</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># swag2mcp — только локальные данные</span></span>
<span class="line"><span>.swag2mcp/cache/</span></span>
<span class="line"><span>.swag2mcp/responses/</span></span></code></pre></div><p>Директории <code>cache/</code> и <code>responses/</code> содержат локальные данные, специфичные для машины, которые не следует коммитить. Всё остальное (<code>swag2mcp.yaml</code>, <code>specs/</code>, <code>auth_scripts/</code>) должно быть в репозитории, чтобы конфигурация была общей для всей команды.</p>`,66)])])}const g=s(n,[["render",p]]);export{k as __pageData,g as default};
